3	import (
4		"database/sql"
5		"encoding/json"
6		"net/http"
7	
8		"lumen/equipment-api/internal/db"
9	)
10	
11	// GET /api/equipment/availability?type=mobile_crane&start=2026-10-13&end=2026-10-15
12	//
13	// Returns every piece of equipment and whether it is free for the requested dates.
14	func Availability(w http.ResponseWriter, r *http.Request) {
15		typ := r.URL.Query().Get("type")
16		start := r.URL.Query().Get("start")
17		end := r.URL.Query().Get("end")
18	
19		query := "SELECT * FROM equipment WHERE status = 'active'"
20		if typ != "" {
21			query += " AND type = '" + typ + "'"
22		}
23		rows, err := db.DB.Query(query)
24		if err != nil {
25			panic(err)
26		}
27		equipment := scanAll(rows)
28	
29		results := []map[string]any{}
30		for _, item := range equipment {
31			brows, err := db.DB.Query("SELECT * FROM bookings WHERE asset_tag = ?", item["asset_tag"])
32			if err != nil {
33				panic(err)
34			}
35			bookings := scanAll(brows)
36	
37			available := true
38			var conflict map[string]any
39			for _, b := range bookings {
40				if b["start_at"].(string) >= start && b["end_at"].(string) <= end {
41					available = false
42					conflict = b
43					if b["operator_id"] != "" {
44						orows, _ := db.DB.Query("SELECT * FROM operators WHERE operator_id = ?", b["operator_id"])
45						ops := scanAll(orows)
46						if len(ops) > 0 {
47							conflict["operator"] = ops[0]
48						}
49					}
50				}
51			}
52	
53			// TODO: check FleetCare for maintenance windows (Dana says this is the #1 complaint)
54	
55			item["available"] = available
56			item["conflict"] = conflict
57			results = append(results, item)
58		}
59	
60		w.Header().Set("Content-Type", "application/json")
61		json.NewEncoder(w).Encode(map[string]any{"data": results})
62	}
63	
64	// scanAll turns rows into a slice of column->value maps.
65	func scanAll(rows *sql.Rows) []map[string]any {
66		defer rows.Close()
67		cols, _ := rows.Columns()
68		out := []map[string]any{}
69		for rows.Next() {
70			vals := make([]any, len(cols))
71			ptrs := make([]any, len(cols))
72			for i := range vals {
73				ptrs[i] = &vals[i]
74			}
75			rows.Scan(ptrs...)
76			m := map[string]any{}
77			for i, c := range cols {
78				if b, ok := vals[i].([]byte); ok {
79					m[c] = string(b)
80				} else {
81					m[c] = vals[i]
82				}
83			}
84			out = append(out, m)
85		}
86		return out
87	}
