for (const b of bookings) {
  const bs = bucket(b.start)[0], be = bucket(b.end)[0]; // just the letter prefix
  if (bs !== be) { mixedRow++; if (mixedExamples.length < 5) mixedExamples.push({id:b.booking_id, start:b.start, end:b.end}); }
}
