// Throwaway: simulate a naive check-then-insert reservation against the SAME
// sqlite file from two separate OS processes, to observe real locking behavior
// of node:sqlite (DatabaseSync). Not part of the app; no schema/app code touched.
import { DatabaseSync } from "node:sqlite";

const dbPath = process.argv[2];
const label = process.argv[3];
const db = new DatabaseSync(dbPath);

function log(msg) { console.log(`[ts-${label}] ${msg}`); }

try {
  db.exec("BEGIN IMMEDIATE");
  log("began txn, checking for conflict...");
  const existing = db.prepare("SELECT COUNT(*) as n FROM race_bookings WHERE asset_tag='CT-001'").get();
  // widen the race window deliberately
  const until = Date.now() + 300;
  while (Date.now() < until) { /* busy-wait, keep txn open */ }
  if (existing.n > 0) {
    log(`would conflict (existing=${existing.n}) -- rolling back`);
    db.exec("ROLLBACK");
  } else {
    db.prepare("INSERT INTO race_bookings (asset_tag, who) VALUES ('CT-001', ?)").run(label);
    db.exec("COMMIT");
    log("inserted and committed - WON the race");
  }
} catch (e) {
  log(`ERROR: ${e.message}`);
}
db.close();

