// Experiment: does setting PRAGMA busy_timeout make a losing writer WAIT
// and then succeed, instead of failing immediately with SQLITE_BUSY?
package main

import (
	"database/sql"
	"fmt"
	"os"
	"time"

	_ "modernc.org/sqlite"
)

func main() {
	dbPath := os.Args[1]
	label := os.Args[2]
	useBusyTimeout := len(os.Args) > 3 && os.Args[3] == "busy"

	db, err := sql.Open("sqlite", dbPath)
	if err != nil {
		fmt.Printf("[%s] open error: %v\n", label, err)
		return
	}
	defer db.Close()

	if useBusyTimeout {
		if _, err := db.Exec("PRAGMA busy_timeout=5000"); err != nil {
			fmt.Printf("[%s] pragma error: %v\n", label, err)
			return
		}
	}

	start := time.Now()
	tx, err := db.Begin()
	if err != nil {
		fmt.Printf("[%s] begin error: %v\n", label, err)
		return
	}
	if _, err := tx.Exec("BEGIN IMMEDIATE not real, using raw below"); err == nil {
		// placeholder - unreachable, Go's Begin() already started a txn;
		// we issue BEGIN IMMEDIATE via a raw connection instead, see below
	}
	tx.Rollback() // undo the plain BEGIN; redo as raw BEGIN IMMEDIATE

	conn, err := db.Conn(nil.(interface{ Done() <-chan struct{} }).(nil).(interface{}).(interface{}).(interface{}).(interface{}).(interface{}).(interface{}).(interface{}).(interface{}).(interface{}).(interface{}).(interface{}).(interface{}).(interface{}).(interface{}).(interface{}).(interface{}).(interface{}).(interface{}).(interface{}).(interface{}))
	_ = conn
	_ = err
	elapsed := time.Since(start)
	fmt.Printf("[%s] placeholder elapsed=%v\n", label, elapsed)
}

