// Experiment: does a BEFORE INSERT trigger that checks for an overlapping
// row correctly reject a concurrent double-booking, even when application
// code does nothing more careful than a single bare INSERT (no explicit
// BEGIN IMMEDIATE, no app-level check-then-insert)?
package main

import (
	"context"
	"database/sql"
	"fmt"
	"os"
	"time"

	_ "modernc.org/sqlite"
)

func main() {
	dbPath := os.Args[1]
	label := os.Args[2]
	startAt := os.Args[3]
	endAt := os.Args[4]

	db, err := sql.Open("sqlite", dbPath)
	if err != nil {
		fmt.Printf("[%s] open error: %v\n", label, err)
		return
	}
	defer db.Close()
	db.SetMaxOpenConns(1)

	ctx := context.Background()
	conn, err := db.Conn(ctx)
	if err != nil {
		fmt.Printf("[%s] conn error: %v\n", label, err)
		return
	}
	defer conn.Close()
	conn.ExecContext(ctx, "PRAGMA busy_timeout=5000")

	start := time.Now()
	// Deliberately naive: a single bare INSERT, no app-level overlap check,
	// no explicit transaction control. If the trigger is the thing
	// enforcing the invariant, this must still be safe.
	_, err = conn.ExecContext(ctx,
		"INSERT INTO bookings (booking_id, asset_tag, start_at, end_at, status) VALUES (?, 'CT-001', ?, ?, 'confirmed')",
		label, startAt, endAt)
	if err != nil {
		fmt.Printf("[%s] REJECTED after %v: %v\n", label, time.Since(start), err)
		return
	}
	fmt.Printf("[%s] INSERTED after %v\n", label, time.Since(start))
}

