	"fmt"

	sqlite3 "modernc.org/sqlite"
	sqlite3lib "modernc.org/sqlite/lib"
)

func main() {
	db, _ := sql.Open("sqlite", "../trig1.db")
	defer db.Close()
	_, err := db.Exec("INSERT INTO bookings (booking_id, asset_tag, start_at, end_at, status) VALUES ('X','CT-001','2026-11-12 08:00','2026-11-12 08:30','confirmed')")
	fmt.Printf("raw error: %v\ntype: %T\n", err, err)
	var serr *sqlite3.Error
	if errors.As(err, &serr) {
		fmt.Printf("Code()=%d  SQLITE_CONSTRAINT_TRIGGER=%d  SQLITE_CONSTRAINT=%d\n",
			serr.Code(), sqlite3lib.SQLITE_CONSTRAINT_TRIGGER, sqlite3lib.SQLITE_CONSTRAINT)
	} else {
		fmt.Println("not a *sqlite3.Error via errors.As")
	}
}

